for i in range(2):
    print("inside")   # indented = part of the loop
print("outside")

for letter in "abc":
    print(letter)
for i in range(3):
    print(i)   # 0 1 2

for n in [1, 2, 3, 4]:
    if n == 3:
        break
    print(n)   # 1 2

for n in [1, 2, 3]:
    if n == 2:
        continue
    print(n)   # 1 3

def double(n):
    return n * 2

print(double(21))   # 42

def greet(who):
    print(f"hi {who}")

greet("Ada")

def total(*numbers):
    return sum(numbers)

print(total(1, 2, 3))   # 6

def first_even(numbers):
    for n in numbers:
        if n % 2 == 0:
            return n

print(first_even([3, 5, 8]))   # 8

def noop():
    pass

print(noop())   # None

scores = {"ana": 9, "bo": 7}
print(scores["ana"])          # 9
print(scores.get("cai", 0))   # 0

counts = {}
counts["a"] = counts.get("a", 0) + 1
print(counts)   # {'a': 1}

words = ["hi", "there"]
lengths = {w: len(w) for w in words}
print(lengths)   # {'hi': 2, 'there': 5}

